{
  "diagnoses": [
    {
      "id": "hardcoded-repo-paths",
      "summary": "maven-build-lifecycle/SKILL.md hardcodes a specific repository path (google/auto) and patch output path, making the skill non-reusable and conflicting with the task prompt’s required /home/travis/build/failed/<repo>/<id>/patch_{i}.diff locations.",
      "details": [
        "The 'Build-repair artifact contract' section mandates `/home/travis/build/failed/google/auto/patch_1.diff`.",
        "The 'Minimal diagnostic sequence' section uses `cd /home/travis/build/failed/google/auto`.",
        "This contradicts the trial instruction that the repo is at `/home/travis/build/failed/<repo>/<id>` and patch files must be written under that same directory."
      ],
      "impact": "Users following the skill will write artifacts to the wrong location and run commands in the wrong directory, causing the meta-task to be judged incorrect even if the actual project repair is correct."
    },
    {
      "id": "over-prescriptive-jdk7-and-command",
      "summary": "The skill claims 'reproduce target CI' but then effectively forces JDK 7 switching and a specific Maven command (`-f build-pom.xml verify ...`), which is not generally valid and can mislead repairs for projects/CI that use different JDKs or commands.",
      "details": [
        "The document emphasizes reading CI config first, but the concrete workflow sections prescribe JDK 7 and a specific command as the default.",
        "Hardcoding `-f build-pom.xml` assumes the presence of a nonstandard reactor POM; many repos do not have this file."
      ],
      "impact": "Following the skill may reproduce the wrong environment, chase non-CI failures, or fail to reproduce at all due to nonexistent files/incorrect JDK."
    },
    {
      "id": "missing-nested-test-project-dependency-guidance",
      "summary": "Per the location hint, the skill should cover nested test project dependency resolution and modification scope (common in Maven Invoker / integration-test fixtures), but maven-build-lifecycle/SKILL.md lacks concrete guidance on diagnosing/fixing dependency issues in nested test projects and limiting changes appropriately.",
      "details": [
        "No section explains how Maven Invoker-style nested projects (often under src/it or similar) resolve parents/dependencies.",
        "No guidance on when it is appropriate to edit nested fixture POMs vs. fixing the main reactor so the nested projects build correctly.",
        "No explicit 'modification scope' constraints for fixtures vs. production modules (important for minimizing changes and avoiding altering test fixtures unnecessarily)."
      ],
      "impact": "For builds failing in invoker/nested integration test projects, the skill provides insufficient direction, leading to either overbroad changes or ineffective fixes."
    }
  ],
  "affected_files": [
    "maven-build-lifecycle/SKILL.md"
  ],
  "repair_plan": [
    {
      "step": 1,
      "action": "Remove hardcoded repository-specific paths and replace with placeholders aligned to the task prompt.",
      "edits": [
        "Change any `cd /home/travis/build/failed/google/auto` to `cd /home/travis/build/failed/<repo>/<id>` (or 'the repository path given by the task').",
        "Change the patch artifact requirement from `/home/travis/build/failed/google/auto/patch_1.diff` to `/home/travis/build/failed/<repo>/<id>/patch_1.diff` and clarify to follow the task’s required path if different."
      ]
    },
    {
      "step": 2,
      "action": "Make JDK switching and Maven command selection conditional on the repository’s CI configuration rather than fixed defaults.",
      "edits": [
        "Keep the JDK 7 switcher example, but frame it as conditional: only switch when CI declares that JDK.",
        "Replace the single hardcoded Maven command with guidance: run the exact CI command; provide examples for both default `pom.xml` and alternate `-f <reactor-pom>` when CI indicates it."
      ]
    },
    {
      "step": 3,
      "action": "Add a dedicated section to maven-build-lifecycle/SKILL.md on nested test projects (e.g., Maven Invoker integration tests) focusing on dependency resolution and minimal modification scope.",
      "edits": [
        "Explain common failure modes: nested project parent `<relativePath>` issues, unresolved parent POMs, fixtures depending on reactor artifacts not yet installed, mismatched groupId/artifactId/version usage.",
        "Provide a minimal diagnostic checklist: identify whether failure occurs in invoker/IT phase; locate nested POMs; inspect parent linkage; confirm whether the main modules are built/installed before invoker runs (and how CI does it).",
        "Add explicit modification-scope rules: prefer fixing the main reactor/build configuration so nested fixtures resolve dependencies; only edit nested fixture POMs when the fixture itself is incorrect and CI expects it to be corrected."
      ]
    }
  ],
  "preservation_constraints": [
    "Preserve the overall structure and existing legacy-CI emphasis (reproduce CI first; avoid unnecessary modernization).",
    "Do not remove existing notes about Invoker/integration tests; extend them with nested-project guidance rather than replacing them wholesale.",
    "Keep examples (like jdk_switcher) but ensure they are presented as conditional patterns, not mandatory steps.",
    "Do not introduce repository-specific assumptions (paths, module names, build-pom.xml) except as clearly labeled examples."
  ],
  "confidence": 0.74
}
